// Parse the AI agent output and ensure it's valid JSON
let aiOutput = $input.first().json.output;

// Remove any markdown formatting if present
if (typeof aiOutput === 'string') {
  // Remove backticks and json markers
  aiOutput = aiOutput.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  try {
    // Parse the cleaned string to JSON
    aiOutput = JSON.parse(aiOutput);
  } catch (error) {
    // If parsing fails, create a default structure
    return [{
      json: {
        error: "Failed to parse AI output",
        originalOutput: aiOutput,
        defaultPayload: {
          "inputText": "Create a presentation about: " + $input.first().json.chatInput,
          "format": "presentation",
          "textMode": "generate",
          "numCards": 10,
          "cardSplit": "auto",
          "textOptions": {
            "amount": "detailed",
            "tone": "professional",
            "language": "en"
          },
          "imageOptions": {
            "source": "aiGenerated",
            "model": "flux-1-pro",
            "style": "professional, modern"
          }
        }
      }
    }];
  }
}

// Return the parsed JSON
return [{
  json: aiOutput
}];

// Get the generation ID from the Gamma API response
const generationId = $input.first().json.generationId;

// Construct the Gamma presentation URL
const gammaUrl = `https://gamma.app/docs/${generationId}`;

// Get the original chat input for context
const originalRequest = $input.all()[0].json.inputText || "Your presentation";

// Prepare the response message
const responseMessage = {
  success: true,
  message: `✅ Your presentation has been created successfully!`,
  presentationUrl: gammaUrl,
  generationId: generationId,
  topic: originalRequest.substring(0, 100) + "...",
  instructions: [
    "Click the link above to view your presentation",
    "The presentation may take a few moments to fully generate",
    "You can edit and customize it further in Gamma"
  ],
  timestamp: new Date().toISOString()
};

return [{
  json: responseMessage
}];
